"""Round 3 summary: results/r3-<ts>/summary.md from the stage outputs (prep, size, size2, access_eq, access_orig, pr3917).

Usage: python r3_summary.py <out_dir>
"""

import json
import sys
from pathlib import Path


def read(p):
    try:
        return Path(p).read_text()
    except OSError:
        return None


def main():
    out = Path(sys.argv[1])
    L = [f"# DATA-11 round 3 ({out.name}): equal-size files, and PR #3917 on layouts", "",
         "Auto-generated by the job. Numbers are measured; interpretation is in the session report.", ""]
    prep = json.loads(read(out / "prep" / "prep.json") or "{}")
    if prep:
        L += ["## Equal-size variants", "",
              f"Cuts uploaded to `{prep.get('r3_prefix')}` at `{(prep.get('upload') or {}).get('revision')}`. Stream copy (PyAV packet remux), "
              "each cut starts at a keyframe, pts rebased to 0.", "",
              "| layout | group | part | frames [a, b) | frames | MB | check |", "|---|---|---|---|---|---|---|"]
        for r in prep.get("cuts", []):
            c = r["check"]
            L.append(f"| {r['layout']} | {r['group']} | {r['part']} | [{r['from_frame']}, {r['to_frame']}) | {r['frames']} | {r['bytes'] / 1e6:.1f} | "
                     f"{'pass' if c['pass'] else 'FAIL'} ({c['frames_checked']} frames, packets {c['packets_ok']}, pts {c['pts_ok']}, "
                     f"bytes {c['bytes_ok']}) |")
        ss = prep.get("sep_sizes", {})
        if ss:
            L += ["", f"SEP files (unchanged): {', '.join(f'{v / 1e6:.0f}' for v in ss.values())} MB."]
        for k, v in (prep.get("datasets") or {}).items():
            L.append(f"- dataset {k}: {v.get('repo', 'local')} @ {str(v.get('commit'))[:10]}, {v.get('episodes')} episodes, {v.get('frames')} frames, "
                     f"{v.get('video_files_per_key')} video files per key")
        L.append("")
    for tag in ("size", "size2"):
        t = read(out / tag / "summary.md")
        if t:
            L += [t.replace("# ", "## ", 1), ""]
    for tag, title in (("access_eq", "Random access, equal-size files"), ("access_orig", "Random access, control: round-2 files (3x bigger)")):
        t = read(out / tag / "summary.md")
        if t:
            body = t.split("\n", 1)[1] if t.startswith("#") else t
            L += [f"## {title}", body.replace("## ", "### "), ""]
    t = read(out / "pr3917" / "summary.md")
    if t:
        L += [t.replace("# ", "## ", 1).replace("\n## ", "\n### "), ""]
    st = read(out / "STATUS.tsv")
    if st:
        L += ["## Stages", "", "```", st.strip(), "```"]
    (out / "summary.md").write_text("\n".join(L) + "\n")
    print(f"wrote {out / 'summary.md'} ({len(L)} lines)")


if __name__ == "__main__":
    main()
